-- EXPERIMENTAL BD2-02B. NO MIGRACION DEL BACKEND.

-- Fuente SHA256: fb6ab07cfdfee38ba59e1acc879335ec0b377150acc3474b4a817a9eece229d7

-- 28 tablas, 144 columnas, 28 PK, 40 FK, 19 UNIQUE.

BEGIN;

CREATE TABLE "rol" (
  "id_rol" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombre" VARCHAR(40) NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "pk_rol" PRIMARY KEY ("id_rol"),
  CONSTRAINT "uq_rol_1" UNIQUE ("nombre")
);

CREATE TABLE "permiso" (
  "id_permiso" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "codigo" VARCHAR(80) NOT NULL,
  "descripcion" TEXT NOT NULL,
  CONSTRAINT "pk_permiso" PRIMARY KEY ("id_permiso"),
  CONSTRAINT "uq_permiso_1" UNIQUE ("codigo")
);

CREATE TABLE "rol_permiso" (
  "id_rol" INTEGER NOT NULL,
  "id_permiso" INTEGER NOT NULL,
  CONSTRAINT "pk_rol_permiso" PRIMARY KEY ("id_rol", "id_permiso"),
  CONSTRAINT "fk_rol_permiso_1" FOREIGN KEY ("id_rol") REFERENCES "rol" ("id_rol"),
  CONSTRAINT "fk_rol_permiso_2" FOREIGN KEY ("id_permiso") REFERENCES "permiso" ("id_permiso")
);

CREATE TABLE "usuario" (
  "id_usuario" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_rol" INTEGER NOT NULL,
  "nombre" VARCHAR(120) NOT NULL,
  "correo" VARCHAR(200) NOT NULL,
  "clave_hash" VARCHAR(255) NOT NULL,
  "activo" BOOLEAN NOT NULL DEFAULT true,
  CONSTRAINT "pk_usuario" PRIMARY KEY ("id_usuario"),
  CONSTRAINT "uq_usuario_1" UNIQUE ("correo"),
  CONSTRAINT "fk_usuario_1" FOREIGN KEY ("id_rol") REFERENCES "rol" ("id_rol")
);

CREATE TABLE "grupo_academico" (
  "id_grupo" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_profesor" INTEGER NOT NULL,
  "nombre" VARCHAR(120) NOT NULL,
  "periodo" VARCHAR(30) NOT NULL,
  CONSTRAINT "pk_grupo_academico" PRIMARY KEY ("id_grupo"),
  CONSTRAINT "fk_grupo_academico_1" FOREIGN KEY ("id_profesor") REFERENCES "usuario" ("id_usuario")
);

CREATE TABLE "consentimiento" (
  "id_consentimiento" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_estudiante" INTEGER NOT NULL,
  "version_texto" VARCHAR(30) NOT NULL,
  "fecha_aceptacion" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "fecha_revocacion" TIMESTAMP WITHOUT TIME ZONE,
  CONSTRAINT "pk_consentimiento" PRIMARY KEY ("id_consentimiento"),
  CONSTRAINT "fk_consentimiento_1" FOREIGN KEY ("id_estudiante") REFERENCES "usuario" ("id_usuario")
);

CREATE TABLE "caso" (
  "id_caso" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_profesor" INTEGER NOT NULL,
  "titulo" VARCHAR(160) NOT NULL,
  "introduccion_teorica" TEXT NOT NULL,
  "estado" VARCHAR(20) NOT NULL DEFAULT 'borrador',
  "fecha_creacion" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "fecha_validacion" TIMESTAMP WITHOUT TIME ZONE,
  CONSTRAINT "pk_caso" PRIMARY KEY ("id_caso"),
  CONSTRAINT "fk_caso_1" FOREIGN KEY ("id_profesor") REFERENCES "usuario" ("id_usuario")
);

CREATE TABLE "grupo_estudiante" (
  "id_grupo_estudiante" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_grupo" INTEGER NOT NULL,
  "id_estudiante" INTEGER NOT NULL,
  "fecha_ingreso" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "activo" BOOLEAN NOT NULL DEFAULT true,
  CONSTRAINT "pk_grupo_estudiante" PRIMARY KEY ("id_grupo_estudiante"),
  CONSTRAINT "uq_grupo_estudiante_1" UNIQUE ("id_grupo", "id_estudiante"),
  CONSTRAINT "fk_grupo_estudiante_1" FOREIGN KEY ("id_grupo") REFERENCES "grupo_academico" ("id_grupo"),
  CONSTRAINT "fk_grupo_estudiante_2" FOREIGN KEY ("id_estudiante") REFERENCES "usuario" ("id_usuario")
);

CREATE TABLE "objetivo_aprendizaje" (
  "id_objetivo" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_caso" INTEGER NOT NULL,
  "descripcion" TEXT NOT NULL,
  "orden" INTEGER NOT NULL,
  CONSTRAINT "pk_objetivo_aprendizaje" PRIMARY KEY ("id_objetivo"),
  CONSTRAINT "uq_objetivo_aprendizaje_1" UNIQUE ("id_caso", "orden"),
  CONSTRAINT "fk_objetivo_aprendizaje_1" FOREIGN KEY ("id_caso") REFERENCES "caso" ("id_caso")
);

CREATE TABLE "escena" (
  "id_escena" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_caso" INTEGER NOT NULL,
  "titulo" VARCHAR(160) NOT NULL,
  "contexto" TEXT NOT NULL,
  "orden" INTEGER NOT NULL,
  "tipo" VARCHAR(30) NOT NULL,
  CONSTRAINT "pk_escena" PRIMARY KEY ("id_escena"),
  CONSTRAINT "uq_escena_1" UNIQUE ("id_caso", "orden"),
  CONSTRAINT "fk_escena_1" FOREIGN KEY ("id_caso") REFERENCES "caso" ("id_caso")
);

CREATE TABLE "personaje" (
  "id_personaje" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_caso" INTEGER NOT NULL,
  "nombre" VARCHAR(100) NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "pk_personaje" PRIMARY KEY ("id_personaje"),
  CONSTRAINT "fk_personaje_1" FOREIGN KEY ("id_caso") REFERENCES "caso" ("id_caso")
);

CREATE TABLE "rubrica" (
  "id_rubrica" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_caso" INTEGER NOT NULL,
  "nombre" VARCHAR(120) NOT NULL,
  "nota_maxima" NUMERIC(4,2) NOT NULL,
  CONSTRAINT "pk_rubrica" PRIMARY KEY ("id_rubrica"),
  CONSTRAINT "uq_rubrica_1" UNIQUE ("id_caso"),
  CONSTRAINT "fk_rubrica_1" FOREIGN KEY ("id_caso") REFERENCES "caso" ("id_caso")
);

CREATE TABLE "asignacion_caso" (
  "id_asignacion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_grupo" INTEGER NOT NULL,
  "id_caso" INTEGER NOT NULL,
  "apertura" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "cierre" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "fecha_limite_ingreso" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "intentos_base" INTEGER NOT NULL DEFAULT 1,
  "tiempo_maximo_min" INTEGER NOT NULL,
  "codigo_acceso_hash" VARCHAR(255) NOT NULL,
  "estado" VARCHAR(20) NOT NULL DEFAULT 'programada',
  CONSTRAINT "pk_asignacion_caso" PRIMARY KEY ("id_asignacion"),
  CONSTRAINT "fk_asignacion_caso_1" FOREIGN KEY ("id_grupo") REFERENCES "grupo_academico" ("id_grupo"),
  CONSTRAINT "fk_asignacion_caso_2" FOREIGN KEY ("id_caso") REFERENCES "caso" ("id_caso")
);

CREATE TABLE "personaje_escena" (
  "id_personaje" INTEGER NOT NULL,
  "id_escena" INTEGER NOT NULL,
  CONSTRAINT "pk_personaje_escena" PRIMARY KEY ("id_personaje", "id_escena"),
  CONSTRAINT "fk_personaje_escena_1" FOREIGN KEY ("id_personaje") REFERENCES "personaje" ("id_personaje"),
  CONSTRAINT "fk_personaje_escena_2" FOREIGN KEY ("id_escena") REFERENCES "escena" ("id_escena")
);

CREATE TABLE "criterio_rubrica" (
  "id_criterio" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_rubrica" INTEGER NOT NULL,
  "nombre" VARCHAR(120) NOT NULL,
  "peso_porcentaje" NUMERIC(5,2) NOT NULL,
  CONSTRAINT "pk_criterio_rubrica" PRIMARY KEY ("id_criterio"),
  CONSTRAINT "fk_criterio_rubrica_1" FOREIGN KEY ("id_rubrica") REFERENCES "rubrica" ("id_rubrica")
);

CREATE TABLE "participacion" (
  "id_participacion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_asignacion" INTEGER NOT NULL,
  "id_grupo_estudiante" INTEGER NOT NULL,
  "estado" VARCHAR(20) NOT NULL DEFAULT 'pendiente',
  "fecha_registro" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  CONSTRAINT "pk_participacion" PRIMARY KEY ("id_participacion"),
  CONSTRAINT "uq_participacion_1" UNIQUE ("id_asignacion", "id_grupo_estudiante"),
  CONSTRAINT "fk_participacion_1" FOREIGN KEY ("id_asignacion") REFERENCES "asignacion_caso" ("id_asignacion"),
  CONSTRAINT "fk_participacion_2" FOREIGN KEY ("id_grupo_estudiante") REFERENCES "grupo_estudiante" ("id_grupo_estudiante")
);

CREATE TABLE "retroalimentacion_docente" (
  "id_retroalimentacion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_asignacion" INTEGER NOT NULL,
  "id_profesor" INTEGER NOT NULL,
  "texto" TEXT NOT NULL,
  "fecha_registro" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  CONSTRAINT "pk_retroalimentacion_docente" PRIMARY KEY ("id_retroalimentacion"),
  CONSTRAINT "uq_retroalimentacion_docente_1" UNIQUE ("id_asignacion"),
  CONSTRAINT "fk_retroalimentacion_docente_1" FOREIGN KEY ("id_asignacion") REFERENCES "asignacion_caso" ("id_asignacion"),
  CONSTRAINT "fk_retroalimentacion_docente_2" FOREIGN KEY ("id_profesor") REFERENCES "usuario" ("id_usuario")
);

CREATE TABLE "notificacion" (
  "id_notificacion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_usuario" INTEGER NOT NULL,
  "id_asignacion" INTEGER,
  "tipo" VARCHAR(40) NOT NULL,
  "mensaje" TEXT NOT NULL,
  "fecha_creacion" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "fecha_envio" TIMESTAMP WITHOUT TIME ZONE,
  "fecha_lectura" TIMESTAMP WITHOUT TIME ZONE,
  CONSTRAINT "pk_notificacion" PRIMARY KEY ("id_notificacion"),
  CONSTRAINT "fk_notificacion_1" FOREIGN KEY ("id_usuario") REFERENCES "usuario" ("id_usuario"),
  CONSTRAINT "fk_notificacion_2" FOREIGN KEY ("id_asignacion") REFERENCES "asignacion_caso" ("id_asignacion")
);

CREATE TABLE "decision" (
  "id_decision" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_escena" INTEGER NOT NULL,
  "id_criterio" INTEGER NOT NULL,
  "enunciado" TEXT NOT NULL,
  "orden" INTEGER NOT NULL,
  CONSTRAINT "pk_decision" PRIMARY KEY ("id_decision"),
  CONSTRAINT "uq_decision_1" UNIQUE ("id_escena", "orden"),
  CONSTRAINT "fk_decision_1" FOREIGN KEY ("id_escena") REFERENCES "escena" ("id_escena"),
  CONSTRAINT "fk_decision_2" FOREIGN KEY ("id_criterio") REFERENCES "criterio_rubrica" ("id_criterio")
);

CREATE TABLE "nivel_criterio" (
  "id_nivel" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_criterio" INTEGER NOT NULL,
  "nombre" VARCHAR(80) NOT NULL,
  "logro_porcentaje" NUMERIC(5,2) NOT NULL,
  CONSTRAINT "pk_nivel_criterio" PRIMARY KEY ("id_nivel"),
  CONSTRAINT "uq_nivel_criterio_1" UNIQUE ("id_nivel", "id_criterio"),
  CONSTRAINT "uq_nivel_criterio_2" UNIQUE ("id_criterio", "nombre"),
  CONSTRAINT "fk_nivel_criterio_1" FOREIGN KEY ("id_criterio") REFERENCES "criterio_rubrica" ("id_criterio")
);

CREATE TABLE "permiso_intento_extra" (
  "id_permiso_extra" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_participacion" INTEGER NOT NULL,
  "id_profesor" INTEGER NOT NULL,
  "cantidad_autorizada" INTEGER NOT NULL DEFAULT 1,
  "justificacion" TEXT NOT NULL,
  "fecha_autorizacion" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  CONSTRAINT "pk_permiso_intento_extra" PRIMARY KEY ("id_permiso_extra"),
  CONSTRAINT "fk_permiso_intento_extra_1" FOREIGN KEY ("id_participacion") REFERENCES "participacion" ("id_participacion"),
  CONSTRAINT "fk_permiso_intento_extra_2" FOREIGN KEY ("id_profesor") REFERENCES "usuario" ("id_usuario")
);

CREATE TABLE "resultado_participacion" (
  "id_resultado_participacion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_participacion" INTEGER NOT NULL,
  "situacion" VARCHAR(20) NOT NULL,
  "nota_definitiva" NUMERIC(4,2) NOT NULL,
  "fecha_calculo" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "observacion" TEXT,
  CONSTRAINT "pk_resultado_participacion" PRIMARY KEY ("id_resultado_participacion"),
  CONSTRAINT "uq_resultado_participacion_1" UNIQUE ("id_participacion"),
  CONSTRAINT "fk_resultado_participacion_1" FOREIGN KEY ("id_participacion") REFERENCES "participacion" ("id_participacion")
);

CREATE TABLE "opcion_respuesta" (
  "id_opcion" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_decision" INTEGER NOT NULL,
  "id_escena_destino" INTEGER,
  "texto" TEXT NOT NULL,
  "es_correcta" BOOLEAN NOT NULL,
  "justificacion_teorica" TEXT NOT NULL,
  "orden" INTEGER NOT NULL,
  CONSTRAINT "pk_opcion_respuesta" PRIMARY KEY ("id_opcion"),
  CONSTRAINT "uq_opcion_respuesta_1" UNIQUE ("id_decision", "orden"),
  CONSTRAINT "uq_opcion_respuesta_2" UNIQUE ("id_opcion", "id_decision"),
  CONSTRAINT "fk_opcion_respuesta_1" FOREIGN KEY ("id_decision") REFERENCES "decision" ("id_decision"),
  CONSTRAINT "fk_opcion_respuesta_2" FOREIGN KEY ("id_escena_destino") REFERENCES "escena" ("id_escena")
);

CREATE TABLE "pista" (
  "id_pista" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_decision" INTEGER NOT NULL,
  "texto" TEXT NOT NULL,
  CONSTRAINT "pk_pista" PRIMARY KEY ("id_pista"),
  CONSTRAINT "fk_pista_1" FOREIGN KEY ("id_decision") REFERENCES "decision" ("id_decision")
);

CREATE TABLE "intento" (
  "id_intento" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_participacion" INTEGER NOT NULL,
  "id_consentimiento" INTEGER NOT NULL,
  "id_permiso_extra" INTEGER,
  "numero_intento" INTEGER NOT NULL,
  "estado" VARCHAR(20) NOT NULL,
  "inicio" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "fin" TIMESTAMP WITHOUT TIME ZONE,
  CONSTRAINT "pk_intento" PRIMARY KEY ("id_intento"),
  CONSTRAINT "uq_intento_1" UNIQUE ("id_participacion", "numero_intento"),
  CONSTRAINT "fk_intento_1" FOREIGN KEY ("id_participacion") REFERENCES "participacion" ("id_participacion"),
  CONSTRAINT "fk_intento_2" FOREIGN KEY ("id_consentimiento") REFERENCES "consentimiento" ("id_consentimiento"),
  CONSTRAINT "fk_intento_3" FOREIGN KEY ("id_permiso_extra") REFERENCES "permiso_intento_extra" ("id_permiso_extra")
);

CREATE TABLE "paso_simulacion" (
  "id_paso" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_intento" INTEGER NOT NULL,
  "id_decision" INTEGER NOT NULL,
  "id_opcion" INTEGER NOT NULL,
  "numero_paso" INTEGER NOT NULL,
  "registrado_en" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "tiempo_segundos" INTEGER NOT NULL,
  "reflexion_estudiante" TEXT,
  CONSTRAINT "pk_paso_simulacion" PRIMARY KEY ("id_paso"),
  CONSTRAINT "uq_paso_simulacion_1" UNIQUE ("id_intento", "numero_paso"),
  CONSTRAINT "fk_paso_simulacion_1" FOREIGN KEY ("id_intento") REFERENCES "intento" ("id_intento"),
  CONSTRAINT "fk_paso_simulacion_2" FOREIGN KEY ("id_opcion", "id_decision") REFERENCES "opcion_respuesta" ("id_opcion", "id_decision")
);

CREATE TABLE "resultado_intento" (
  "id_resultado" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_intento" INTEGER NOT NULL,
  "nota_final" NUMERIC(4,2) NOT NULL,
  "fecha_calculo" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  "comentario_automatico" TEXT,
  CONSTRAINT "pk_resultado_intento" PRIMARY KEY ("id_resultado"),
  CONSTRAINT "uq_resultado_intento_1" UNIQUE ("id_intento"),
  CONSTRAINT "fk_resultado_intento_1" FOREIGN KEY ("id_intento") REFERENCES "intento" ("id_intento")
);

CREATE TABLE "resultado_criterio" (
  "id_resultado_criterio" INTEGER GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "id_resultado" INTEGER NOT NULL,
  "id_criterio" INTEGER NOT NULL,
  "id_nivel" INTEGER NOT NULL,
  "puntaje_obtenido" NUMERIC(5,2) NOT NULL,
  CONSTRAINT "pk_resultado_criterio" PRIMARY KEY ("id_resultado_criterio"),
  CONSTRAINT "uq_resultado_criterio_1" UNIQUE ("id_resultado", "id_criterio"),
  CONSTRAINT "fk_resultado_criterio_1" FOREIGN KEY ("id_resultado") REFERENCES "resultado_intento" ("id_resultado"),
  CONSTRAINT "fk_resultado_criterio_2" FOREIGN KEY ("id_nivel", "id_criterio") REFERENCES "nivel_criterio" ("id_nivel", "id_criterio")
);

COMMIT;
